<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>EMBERLINE — 5v5 tactical FPS</title>
<style>
  /* Emberworks look: charcoal foundry, warm ember accent, cool slate second. */
  :root {
    --canvas: #17130f;
    --surface: #241c15;
    --panel: #1d1712;
    --hairline: #3a2f24;
    --ink: #f2e8d5;
    --muted: #9a8f7a;
    --accent: #ff9a2e;
    --ember: #ff7a1a;
    --slate: #7fa8c9;
    --danger: #ff4d2e;
    --good: #8fd18f;
