    --font-ui: system-ui, -apple-system, 'Segoe UI', sans-serif;
    --font-readout: ui-monospace, 'SF Mono', Menlo, monospace;
  }
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    height: 100%;
    overflow: hidden;
    background: var(--canvas);
    color: var(--ink);
    font-family: var(--font-ui);
    user-select: none;
  }
  #game, #game canvas { position: fixed; inset: 0; display: block; }
  #hud { position: fixed; inset: 0; pointer-events: none; }

  /* Crosshair: four ticks whose gap grows with spread (set via --gap). */
  #crosshair { position: fixed; left: 50%; top: 50%; width: 0; height: 0; }
  #crosshair i { position: absolute; background: var(--ink); opacity: .9; box-shadow: 0 0 2px #000; }
  #crosshair i:nth-child(1) { left: -1px; top: calc(-11px - var(--crosshair-gap, 2px)); width: 2px; height: 7px; }
  #crosshair i:nth-child(2) { left: -1px; top: calc(4px + var(--crosshair-gap, 2px)); width: 2px; height: 7px; }
  #crosshair i:nth-child(3) { top: -1px; left: calc(-11px - var(--crosshair-gap, 2px)); height: 2px; width: 7px; }
  #crosshair i:nth-child(4) { top: -1px; left: calc(4px + var(--crosshair-gap, 2px)); height: 2px; width: 7px; }
  #crosshair .dot { position: absolute; left: -1px; top: -1px; width: 2px; height: 2px; background: var(--ink); }

  #hitmarker { position: fixed; left: 50%; top: 50%; width: 26px; height: 26px; transform: translate(-50%, -50%) rotate(45deg); opacity: 0; transition: opacity 90ms linear; }
  #hitmarker.on { opacity: 1; }
  #hitmarker.kill i { background: var(--danger); }
