  #hitmarker i:nth-child(2) { left: 12px; bottom: 0; width: 2px; height: 8px; }
  #hitmarker i:nth-child(3) { top: 12px; left: 0; height: 2px; width: 8px; }
  #hitmarker i:nth-child(4) { top: 12px; right: 0; height: 2px; width: 8px; }

  /* Bottom-left: health + armour. */
  #health { position: fixed; left: 28px; bottom: 26px; width: 220px; }
  #health .row { display: flex; align-items: baseline; gap: 10px; }
  #health-num { font-family: var(--font-readout); font-size: 40px; line-height: 1; }
  #armor-num { font-family: var(--font-readout); font-size: 15px; color: var(--slate); }
  #health-fill { height: 6px; margin-top: 6px; background: var(--hairline); border-radius: 2px; overflow: hidden; }
  #health-fill i { display: block; height: 100%; width: 100%; background: var(--ember); transition: width 120ms linear; }
  #health.low #health-num { color: var(--danger); }
