  #killfeed .ember { color: var(--ember); }
  #killfeed .slate { color: var(--slate); }
  #killfeed .you { color: var(--ink); font-weight: 600; }

  /* Minimap, bottom-centre-left. */
  #minimap { position: fixed; left: 28px; bottom: 118px; border: 1px solid var(--hairline); border-radius: var(--radius); background: rgba(23, 19, 15, .78); }

  /* Centre banner. */
  #banner { position: fixed; left: 50%; top: 34%; transform: translate(-50%, -50%); text-align: center; opacity: 0; transition: opacity 160ms linear; }
  #banner.on { opacity: 1; }
  #banner-title { font-size: 44px; font-weight: 600; letter-spacing: .02em; text-shadow: 0 2px 12px #000; }
  #banner-sub { margin-top: 6px; font-size: 16px; color: var(--muted); text-shadow: 0 1px 6px #000; }

  /* Damage vignette + direction indicator. */
  #damage-vignette { position: fixed; inset: 0; pointer-events: none; opacity: 0; background: radial-gradient(ellipse at center, transparent 55%, rgba(255, 40, 20, .5) 100%); transition: opacity 120ms linear; }
  #damage-dir { position: fixed; left: 50%; top: 50%; width: 120px; height: 120px; margin: -60px 0 0 -60px; opacity: 0; transition: opacity 200ms linear; }
  #damage-dir i { position: absolute; left: 50%; top: 0; margin-left: -14px; border-left: 14px solid transparent; border-right: 14px solid transparent; border-bottom: 22px solid rgba(255, 60, 30, .9); }

  #flash-overlay { position: fixed; inset: 0; background: #fff; opacity: 0; pointer-events: none; }

  /* Buy menu. */
  #buy-menu { position: fixed; left: 50%; top: 50%; transform: translate(-50%, -50%); width: min(620px, 94vw); max-height: 86vh; overflow: auto; background: var(--panel); border: 1px solid var(--hairline); border-radius: 6px; padding: 20px 22px; pointer-events: auto; }
  #buy-menu[hidden] { display: none; }
  #buy-menu h2 { margin: 0 0 2px; font-size: 22px; letter-spacing: .02em; }
  #buy-menu h2 span { color: var(--accent); }
  #buy-money { font-family: var(--font-readout); color: var(--good); font-size: 16px; margin-bottom: 12px; }
  #buy-items { display: grid; gap: 6px; }
  .buy-row { display: flex; align-items: center; gap: 12px; padding: 8px 10px; border: 1px solid var(--hairline); border-radius: var(--radius); cursor: pointer; }
  .buy-row:hover { border-color: var(--accent); }
  .buy-row.owned { border-color: var(--good); }
  .buy-row.poor { opacity: .45; }
  .buy-row .key { font-family: var(--font-readout); font-size: 12px; color: var(--muted); border: 1px solid var(--hairline); border-radius: 3px; padding: 2px 6px; }
  .buy-row .name { flex: 1; font-size: 15px; }
  .buy-row .name small { display: block; font-size: 12px; color: var(--muted); }
  .buy-row .price { font-family: var(--font-readout); color: var(--good); }
  #buy-close { margin-top: 12px; font-size: 13px; color: var(--muted); }

  /* Start / pause / end overlay. */
  .overlay { position: fixed; inset: 0; display: grid; place-items: center; padding: 24px; background: rgba(23, 19, 15, .86); }
  .overlay[hidden] { display: none; }
  .panel { width: min(480px, 100%); padding: 32px; background: var(--surface); border: 1px solid var(--hairline); border-radius: 6px; }
  .panel h1 { margin: 0 0 4px; font-size: 38px; line-height: 1.1; font-weight: 600; letter-spacing: -0.02em; }
  .panel h1 span { color: var(--ember); }
  .panel p { margin: 0 0 24px; font-size: 15px; line-height: 1.5; color: var(--muted); }
  #play { font: inherit; font-weight: 600; padding: 12px 18px; border: 1px solid var(--accent); border-radius: 6px; background: var(--accent); color: var(--canvas); cursor: pointer; }
  #play:hover { background: var(--ink); border-color: var(--ink); }
  #play:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
  .keys { margin: 24px 0 0; padding: 0; list-style: none; display: grid; gap: 8px; font-size: 14px; color: var(--muted); }
  .keys li { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
  .keys kbd { min-width: 24px; padding: 2px 6px; border: 1px solid var(--hairline); border-radius: 3px; font-family: var(--font-readout); font-size: 12px; color: var(--ink); text-align: center; }
  @media (prefers-reduced-motion: reduce) {
    #hitmarker, #banner, #damage-vignette { transition-duration: 0.01ms; }
  }
</style>
