// Waypoint graph — hand-placed nodes on the three lanes, sites and spawns.
// Columns x = -18 / -9 / 0 / 9 / 18, rows z = 12 / 4 / -4, plus site rows.
// ---------------------------------------------------------------------------
const WAYPOINT_DEFS = [
  // id, x, z, links
  [0, -16, 12, [1, 5]],
  [1, -8, 12, [0, 2, 6]],
  [2, 0, 12, [1, 3, 7]],
  [3, 8, 12, [2, 4, 8]],
  [4, 16, 12, [3, 9]],
  [5, -18, 4, [0, 6, 10]],
  [6, -9, 4, [1, 5, 7, 11]],
  [7, 0, 4, [2, 6, 8, 12]],
  [8, 9, 4, [3, 7, 9, 13]],
