  [10, -18, -4, [5, 11, 15]],
  [11, -9, -4, [6, 10, 12, 16]],
  [12, 0, -4, [7, 11, 13, 19]],
  [13, 9, -4, [8, 12, 14, 17]],
  [14, 18, -4, [9, 13, 18]],
  [15, -16, -9, [10, 16, 20]], // Site A
  [16, -9, -9, [11, 15, 17, 19]],
  [17, 9, -9, [13, 16, 18, 19]],
  [18, 16, -9, [14, 17, 21]], // Site B
