  const wallMat = new THREE.MeshStandardMaterial({ color: PALETTE.wall, roughness: 0.9, metalness: 0.08 });
  const metalMat = new THREE.MeshStandardMaterial({ map: metalTex, roughness: 0.55, metalness: 0.55 });
