const MUZZLE_TIME = 0.06;
const MOVE_REFERENCE = 5.4;
const MODEL_POS = { x: 0.24, y: -0.2, z: -0.42 };
const _muzzleWorld = new THREE.Vector3();

function box(w, h, d, material, x, y, z) {
