      tone({ freq: 1108, type: 'sine', dur: 0.09, gain: 0.16, delay: 0.06 });
    },

    // Defuse progress tick.
    defuseTick() {
      if (!ensure()) return;
      tone({ freq: 1568, type: 'square', dur: 0.035, gain: 0.12 });
    },

    // Denied / cannot afford: dull low buzz.
    denied() {
      if (!ensure()) return;
